class AppError extends Error { constructor(code){ super(messages[code] || messages.IO_FAILED); this.name='AppError'; this.code=messages[code]?code:'IO_FAILED'; } }
function fail(code){throw new AppError(code);}
function publicError(error){ const code=error instanceof AppError?error.code:typeof error?.code==='string'&&Object.hasOwn(messages,error.code)?error.code:error?.code==='ENOENT'?'NOT_FOUND':error?.code==='EEXIST'?'EXISTS':error?.name==='AbortError'?'CANCELLED':'IO_FAILED'; return {code,message:messages[code]}; }
module.exports={AppError,fail,publicError};
